-- FAST: optimize five existing RLS policies using initPlan JWT subquery.
-- Existing role access predicates are preserved exactly; no GRANT or new policy.
ALTER POLICY "fast_collab_cases_propose" ON public."fast_discussion_collaboration_cases" WITH CHECK ((fast_discussion_private.can_access_channel(channel_slug) AND (created_by_email = lower((( SELECT auth.jwt() AS jwt) ->> 'email'::text))) AND (status = 'pending'::text) AND (conclusion IS NULL) AND (resolved_at IS NULL) AND ((source_message_id IS NULL) OR (EXISTS ( SELECT 1
   FROM fast_discussion_messages m
  WHERE ((m.id = fast_discussion_collaboration_cases.source_message_id) AND (m.channel_slug = fast_discussion_collaboration_cases.channel_slug) AND (m.sender_kind = 'member'::text) AND (m.sender_email = lower((( SELECT auth.jwt() AS jwt) ->> 'email'::text))))))) AND ((fast_discussion_private."current_role"() = 'owner'::text) OR ((channel_slug <> ALL (ARRAY['direction'::text, 'audit'::text, 'securite'::text])) AND (initiator_agent_code <> ALL (ARRAY['ETIENNE_FAST'::text, 'MAXIME_FAST'::text, 'SECURITY_G'::text, 'AGENT_G'::text])) AND (helper_agent_code <> ALL (ARRAY['ETIENNE_FAST'::text, 'MAXIME_FAST'::text, 'SECURITY_G'::text, 'AGENT_G'::text]))))));
ALTER POLICY "fast_discussion_members_insert" ON public."fast_discussion_members" WITH CHECK (((fast_discussion_private."current_role"() = 'owner'::text) AND (added_by = lower((( SELECT auth.jwt() AS jwt) ->> 'email'::text))) AND (role <> 'owner'::text)));
ALTER POLICY "fast_discussion_members_select" ON public."fast_discussion_members" USING (((fast_discussion_private."current_role"() = 'owner'::text) OR (email = lower((( SELECT auth.jwt() AS jwt) ->> 'email'::text)))));
ALTER POLICY "fast_discussion_messages_insert" ON public."fast_discussion_messages" WITH CHECK ((fast_discussion_private.can_access_channel(channel_slug) AND (sender_kind = 'member'::text) AND (agent_code IS NULL) AND (sender_email = lower((( SELECT auth.jwt() AS jwt) ->> 'email'::text))) AND ((char_length(body) >= 1) AND (char_length(body) <= 5000)) AND ((char_length(sender_name) >= 1) AND (char_length(sender_name) <= 100))));
ALTER POLICY "fast_discussion_requests_insert" ON public."fast_discussion_agent_requests" WITH CHECK ((fast_discussion_private.can_access_channel(channel_slug) AND (requested_by = lower((( SELECT auth.jwt() AS jwt) ->> 'email'::text))) AND (status = 'pending'::text) AND (EXISTS ( SELECT 1
   FROM fast_discussion_messages m
  WHERE ((m.id = fast_discussion_agent_requests.message_id) AND (m.sender_kind = 'member'::text) AND (m.sender_email = lower((( SELECT auth.jwt() AS jwt) ->> 'email'::text))) AND (m.channel_slug = fast_discussion_agent_requests.channel_slug))))));
